import React from 'react';import {createRoot} from 'react-dom/client';import {MemoryRouter} from 'react-router-dom';import JudgementsPage,{printJudgement} from '../../src/components/JudgementsPage.jsx';import {SearchProvider} from '../../src/components/Context/searchcontext.jsx';import {sanitizeJudgementHtml,escapeJudgementText} from '../../src/components/judgementHtml.js';
(async()=>{
const results=[];const wait=ms=>new Promise(r=>setTimeout(r,ms));const assert=(value,message='Assertion failed')=>{if(!value)throw Error(message);};
async function check(name,fn){try{await fn();results.push({name,pass:true});}catch(e){results.push({name,pass:false,error:e.message});}}
const parse=html=>{const d=document.createElement('div');d.innerHTML=sanitizeJudgementHtml(html);return d;};
window.__xss=0;window.__searches=[];window.__saved=[];
window.fetch=async()=>({ok:true,json:async()=>({headnote:'Synthetic headnote'})});
window.__doc={id:'synthetic',title:'Synthetic legal judgement',court:'Supreme Court',date:'2025-01-01',snippet:'<p onclick="window.__xss++">Safe excerpt</p>',fulltext:'<h2>Legal heading</h2><p>Safe full text <a href="javascript:window.__xss++">citation</a></p><svg onload="window.__xss++"></svg>'};
await check('normal legal formatting and citations',()=>{const d=parse('<h2>Judgement</h2><p><strong>AIR 2025 SC 1</strong><br><em>Held</em></p><ul><li>First</li></ul><table><tr><td colspan="2">Order</td></tr></table>');assert(d.querySelector('h2')&&d.querySelector('strong')&&d.querySelector('br')&&d.querySelector('em')&&d.querySelector('li')&&d.querySelector('td').colSpan===2,d.innerHTML);});
await check('scripts removed',()=>assert(!parse('<script>window.__xss++</script><p>Order</p>').querySelector('script')));
await check('event handlers removed',()=>assert(!parse('<p onclick="alert(1)" onmouseover="alert(2)">Text</p>').firstChild.hasAttribute('onclick')));
await check('dangerous and obfuscated URLs removed',()=>{for(const href of ['javascript:alert(1)','java&#10;script:alert(1)','data:text/html,bad','vbscript:bad'])assert(!parse('<a href="'+href+'">Citation</a>').firstChild.hasAttribute('href'));});
await check('safe links and anchors retained',()=>{for(const href of ['https://example.invalid/case','mailto:test@example.invalid','#para1','/case/1'])assert(parse('<a href="'+href+'">Citation</a>').firstChild.hasAttribute('href'));});
await check('SVG math and embedded resources removed',()=>assert(!parse('<svg><a href="javascript:alert(1)">X</a></svg><math><mtext>X</mtext></math><iframe srcdoc="bad"></iframe><img src="/beacon">').querySelector('svg,math,iframe,img')));
await check('styles class id and forms removed',()=>assert(!parse('<style>body{display:none}</style><p style="background:url(https://example.invalid)" id="clobber" class="bad">Order</p><form><input name="x"></form>').querySelector('[style],[id],[class],form,input,style')));
await check('malformed nesting stays inert',()=>{const d=parse('<table><tr><td><svg><style><img src=x onerror=alert(1)></style></svg><p onclick=alert(1)>Held');assert(!d.querySelector('script,svg,img,[onclick],style'));});
await check('Hindi Marathi exact preservation',()=>{const text='????? ?????';assert(parse('<p>'+text+'</p>').textContent===text);});
await check('repeated sanitization stable',()=>{const s=sanitizeJudgementHtml('<p>Order &amp; citation <a href="https://example.invalid">1</a></p>');assert(sanitizeJudgementHtml(s)===s);});
await check('real judgement preview rendering is sanitized',async()=>{createRoot(document.getElementById('root')).render(<MemoryRouter><SearchProvider><JudgementsPage/></SearchProvider></MemoryRouter>);await wait(100);const root=document.getElementById('root');assert(root.textContent.includes('Safe full text'));assert(root.textContent.includes('Safe excerpt'));assert(!root.querySelector('svg[onload],a[href^="javascript:"],[onclick]'));assert(window.__xss===0);});
await check('existing search navigation invokes search hook',async()=>{const input=document.querySelector('input[placeholder^="Search by"]');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,'Synthetic case');input.dispatchEvent(new Event('input',{bubbles:true}));await wait(10);const button=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Search');assert(button);button.click();await wait(30);assert(window.__searches.some(x=>x==='Synthetic case'));});
await check('bookmark callback remains compatible',async()=>{const button=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Save');assert(button,[...document.querySelectorAll("button")].map(b=>b.textContent).join(" | "));button.click();await wait(20);assert(window.__saved.length===1);});
await check('AI headnote renders as text using mocked response',async()=>{const button=[...document.querySelectorAll('button')].find(b=>/AI Headnote/.test(b.textContent));assert(button);button.click();await wait(30);assert(document.body.textContent.includes('Synthetic headnote'));});
await check('actual print output protects HTML body metadata and advocate details',async()=>{const iframe=document.createElement('iframe');document.body.appendChild(iframe);let printed=false;const old=window.open;window.open=()=>({document:iframe.contentDocument,focus(){},print(){printed=true;}});try{printJudgement({...window.__doc,title:'</title><script>window.__xss++</script>',court:'<img onerror=alert(1)>',date:'<img src=x onerror=alert(1)>',citation:'<b>plain citation</b>'},{name:'<img src=x onerror=alert(1)>',notes:'</div><script>bad</script>',letterhead:true});await wait(650);const d=iframe.contentDocument;assert(!d.querySelector('script,img,svg,[onclick],a[href^="javascript:"]'));assert(d.body.textContent.includes('<img src=x onerror=alert(1)>'));assert(d.body.textContent.includes('Safe full text'));assert(d.querySelector('meta[http-equiv="Content-Security-Policy"]'));assert(printed);assert(window.__xss===0);}finally{window.open=old;iframe.remove();}});
await check('text escaping covers HTML delimiters',()=>assert(escapeJudgementText('<>&"\'')==='&lt;&gt;&amp;&quot;&#39;'));
const pre=document.createElement('pre');pre.id='verification-result';pre.textContent=JSON.stringify(results);document.body.appendChild(pre);

})().catch(error=>{const p=document.createElement("pre");p.id="verification-result";p.textContent=JSON.stringify([{name:"fixture",pass:false,error:error.message}]);document.body.appendChild(p);});
